import { useEffect, useState } from "react";
import axios from "axios";

const MyBookings = () => {
  const [bookings, setBookings] = useState([]);
  const [filterStatus, setFilterStatus] = useState("all");
  const [sortBy, setSortBy] = useState("date");

  const [selectedBooking, setSelectedBooking] = useState(null);
  const [showPayModal, setShowPayModal] = useState(false);
  const [showUpdateModal, setShowUpdateModal] = useState(false);

  const [paymentForm, setPaymentForm] = useState({
    name: "",
    cardNumber: "",
    expiry: "",
    cvv: ""
  });

  const [updateForm, setUpdateForm] = useState({
    startDate: "",
    endDate: ""
  });

  const userInfo = JSON.parse(localStorage.getItem("userInfo"));
  const token = userInfo?.token;

  useEffect(() => {
    const fetchBookings = async () => {
      try {
        const { data } = await axios.get(
          "http://localhost:5001/api/bookings/my",
          {
            headers: { Authorization: `Bearer ${token}` }
          }
        );
        setBookings(data);
      } catch (error) {
        console.error(error);
      }
    };

    if (token) fetchBookings();
  }, [token]);

  // ✅ FILTER + SORT
  let filteredBookings =
    filterStatus === "all"
      ? bookings
      : bookings.filter((b) => b.status === filterStatus);

  filteredBookings = [...filteredBookings].sort((a, b) => {
    if (sortBy === "date") {
      return new Date(b.createdAt) - new Date(a.createdAt);
    }
    if (sortBy === "cost") {
      return b.totalCost - a.totalCost;
    }
    return 0;
  });

  return (
    <div style={{ padding: "30px" }}>
      <h2>My Bookings</h2>

      {/* ✅ FILTER + SORT */}
      <div style={{ marginBottom: "15px" }}>
        <label>Status: </label>
        <select onChange={(e) => setFilterStatus(e.target.value)}>
          <option value="all">All</option>
          <option value="pending">Pending</option>
          <option value="confirmed">Confirmed</option>
          <option value="cancelled">Cancelled</option>
        </select>

        <label style={{ marginLeft: "20px" }}>Sort by: </label>
        <select onChange={(e) => setSortBy(e.target.value)}>
          <option value="date">Date</option>
          <option value="cost">Total Cost</option>
        </select>
      </div>

      {/* ✅ TABLE */}
      <table style={table}>
        <thead>
          <tr style={thead}>
            <th style={th}>Unit</th>
            <th style={th}>Start Date</th>
            <th style={th}>End Date</th>
            <th style={th}>Status</th>
            <th style={th}>Total Cost</th>
          </tr>
        </thead>

        <tbody>
          {filteredBookings.map((b) => (
            <tr key={b._id}>
              <td style={td}>{b.unitId?.name || "N/A"}</td>
              <td style={td}>{new Date(b.startDate).toLocaleDateString()}</td>
              <td style={td}>{new Date(b.endDate).toLocaleDateString()}</td>

              <td style={td}>
                <span style={statusStyle(b.status)}>
                  {b.status}
                </span>
              </td>

              <td style={td}>
                ${b.totalCost}

                {/* ✅ PAY BUTTON */}
                {b.status === "pending" && (
                  <button
                    style={payNowBtn}
                    onClick={() => {
                      setSelectedBooking(b);
                      setShowPayModal(true);
                    }}
                  >
                    Pay Now
                  </button>
                )}

                {/* ✅ UPDATE BUTTON */}
                {b.status !== "cancelled" && (
                  <button
                    style={updateBtn}
                    onClick={() => {
                      setSelectedBooking(b);
                      setUpdateForm({
                        startDate: b.startDate.split("T")[0],
                        endDate: b.endDate.split("T")[0]
                      });
                      setShowUpdateModal(true);
                    }}
                  >
                    Update
                  </button>
                )}

                {b.status !== "cancelled" && (
  <button
    style={cancelBtnRow}
    onClick={async () => {
      if (!window.confirm("Cancel this booking?")) return;

      try {
        await axios.put(
          `http://localhost:5001/api/bookings/cancel/${b._id}`,
          {},
          {
            headers: {
              Authorization: `Bearer ${token}`
            }
          }
        );

        alert("✅ Booking cancelled");
        window.location.reload();

      } catch {
        alert("Cancel failed");
      }
    }}
  >
    Cancel
  </button>
)}

              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* ✅ PAYMENT MODAL */}
      {showPayModal && selectedBooking && (
        <div style={overlay}>
          <div style={modal}>
            <h3>Payment Details</h3>

            <p><strong>Unit:</strong> {selectedBooking.unitId?.name}</p>
            <p><strong>Total:</strong> ${selectedBooking.totalCost}</p>

            <input
              placeholder="Name on Card"
              value={paymentForm.name}
              onChange={(e) =>
                setPaymentForm({ ...paymentForm, name: e.target.value })
              }
              style={input}
            />

            <input
              placeholder="Card Number"
              value={paymentForm.cardNumber}
              onChange={(e) =>
                setPaymentForm({ ...paymentForm, cardNumber: e.target.value })
              }
              style={input}
            />

            <div style={{ display: "flex", gap: "10px" }}>
              <input
                placeholder="MM/YY"
                value={paymentForm.expiry}
                onChange={(e) =>
                  setPaymentForm({ ...paymentForm, expiry: e.target.value })
                }
                style={input}
              />

              <input
                placeholder="CVV"
                value={paymentForm.cvv}
                onChange={(e) =>
                  setPaymentForm({ ...paymentForm, cvv: e.target.value })
                }
                style={input}
              />
            </div>

            <button
              style={payBtn}
              onClick={async () => {
                if (
                  !paymentForm.name ||
                  !paymentForm.cardNumber ||
                  !paymentForm.expiry ||
                  !paymentForm.cvv
                ) {
                  alert("Please fill all payment fields");
                  return;
                }

                try {
                  await axios.put(
                    `http://localhost:5001/api/bookings/pay/${selectedBooking._id}`,
                    {},
                    {
                      headers: {
                        Authorization: `Bearer ${token}`
                      }
                    }
                  );

                  alert("✅ Payment successful!");
                  setShowPayModal(false);
                  window.location.reload();

                } catch {
                  alert("Payment failed");
                }
              }}
            >
              Pay Now
            </button>

            <button style={cancelBtn} onClick={() => setShowPayModal(false)}>
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* ✅ UPDATE MODAL */}
      {showUpdateModal && selectedBooking && (
        <div style={overlay}>
          <div style={modal}>
            <h3>Update Booking</h3>

            <label>Start Date</label>
            <input
              type="date"
              value={updateForm.startDate}
              onChange={(e) =>
                setUpdateForm({ ...updateForm, startDate: e.target.value })
              }
              style={input}
            />

            <label>End Date</label>
            <input
              type="date"
              value={updateForm.endDate}
              onChange={(e) =>
                setUpdateForm({ ...updateForm, endDate: e.target.value })
              }
              style={input}
            />

            <button
              style={primaryBtn}
              onClick={async () => {
                try {
                  await axios.put(
                    `http://localhost:5001/api/bookings/update/${selectedBooking._id}`,
                    updateForm,
                    {
                      headers: {
                        Authorization: `Bearer ${token}`
                      }
                    }
                  );

                  alert("✅ Booking updated!");
                  setShowUpdateModal(false);
                  window.location.reload();

                } catch {
                  alert("Update failed");
                }
              }}
            >
              Save Changes
            </button>

            <button style={cancelBtn} onClick={() => setShowUpdateModal(false)}>
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

// ✅ STYLES
const table = { width: "100%", borderCollapse: "collapse" };
const thead = { background: "#1D4ED8", color: "white" };
const th = { padding: "10px", textAlign: "left" };
const td = { padding: "10px", borderBottom: "1px solid #ddd" };

const payNowBtn = {
  marginLeft: "10px",
  padding: "5px 8px",
  background: "#10B981",
  color: "white",
  border: "none",
  borderRadius: "4px"
};

const updateBtn = {
  marginLeft: "10px",
  padding: "5px 8px",
  background: "#F59E0B",
  color: "white",
  border: "none",
  borderRadius: "4px"
};

const statusStyle = (status) => {
  if (status === "confirmed") return { color: "green", fontWeight: "bold" };
  if (status === "pending") return { color: "orange", fontWeight: "bold" };
  return { color: "red" };
};

const overlay = {
  position: "fixed",
  top: 0,
  left: 0,
  width: "100%",
  height: "100%",
  background: "rgba(0,0,0,0.5)",
  display: "flex",
  justifyContent: "center",
  alignItems: "center"
};

const modal = {
  background: "white",
  padding: "25px",
  borderRadius: "10px",
  width: "320px"
};

const input = {
  padding: "8px",
  border: "1px solid #ddd",
  borderRadius: "5px",
  width: "100%",
  marginTop: "10px"
};

const payBtn = {
  background: "#10B981",
  color: "white",
  padding: "10px",
  width: "100%",
  marginTop: "15px",
  border: "none"
};

const primaryBtn = {
  background: "#2563EB",
  color: "white",
  padding: "10px",
  width: "100%",
  marginTop: "10px",
  border: "none"
};

const cancelBtn = {
  marginTop: "10px",
  padding: "8px",
  width: "100%"
};

export default MyBookings;
